package in.kabadiwala.connect.model; import org.springframework.data.annotation.*; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.Document; import java.time.Instant; @Document("transactions") public class Transaction { @Id public String id; @Indexed(unique=true) public String transactionId; @Indexed(unique=true) public String lotId; @Indexed public String collectorId,recyclerId; public String material; public double finalWeight,finalAmount; public String paymentStatus="PENDING",handoverStatus="VERIFIED",status="ACTIVE"; @Indexed(unique=true,sparse=true) public String receiptId; @CreatedDate public Instant createdAt; public Instant completedAt; }